namespace FramePilot {
 static class Program {
  [STAThread] static int Main(string[] args) {
   if(args.Length==2&&args[0]=="--driver-updates")return DriverOffers.Worker(args[1]);
   if(args.Length>0&&args[0]=="--apply-update")return Releases.Swap(args);
   if(args.Contains("--self-test"))return Tests.Run(args.Last());
   if(args.Contains("--test-worker")){System.Threading.Thread.Sleep(30000);return 0;}
   bool own; using(var mutex=new System.Threading.Mutex(true,"Local\\FramePilot-"+System.Security.Principal.WindowsIdentity.GetCurrent().User.Value,out own)) {
    if(!own){MessageBox.Show("FramePilot is already running.");return 1;}
    Application.EnableVisualStyles(); Application.SetCompatibleTextRenderingDefault(false);
    try {Application.Run(new MainForm());return 0;}catch(Exception e){MessageBox.Show(e.Message,"FramePilot couldn't start");return 1;}
   }
  }
 }
