  void GameGuide(){if(guide==null)return;bool comp=quality.SelectedIndex==1;string common="TARGET: "+quality.Text+" | Initial cap: "+cap.Value+" FPS\r\nStart at your gaming monitor's native resolution. Confirm its refresh rate.\r\nReflex On where available; frame generation Off for competitive play.\r\n";string detail="";
   switch(game.Text){case "Valorant":detail="Multithreaded Rendering On. Material/detail/shadows Low; textures Medium or High.\r\nMSAA 2x, anisotropic 8x as a clarity starting point; benchmark lower AA if GPU-bound.\r\nUse a supported 16:9 resolution/aspect mode if ultrawide is letterboxed.\r\nApply in-game. No Valorant config or process is modified.";break;
   case "Fortnite":detail=comp?"Try the current Performance rendering mode in-game; expect reduced visual detail.\r\nShadows/effects/post-processing Low, view distance Medium, textures Medium.\r\nReflex On. Native resolution first; reduce render scale only if GPU-limited.":"DX12; Nanite, Lumen, ray tracing and frame generation Off in-game.\r\nDLSS Quality at ultrawide 1440p; compare native if image detail suffers.\r\nTextures High, view distance Far, shadows Low, effects/post-processing Low.\r\nThe preview lists quality, cap and selected optional config edits.";break;
   case "Call of Duty":detail="Names vary by installed title: Reflex On, frame generation Off; DLSS Quality.\r\nTextures Normal/High; shadows, volumetrics and screen-space reflections Low.\r\nMotion blur and film grain Off. Reduce on-demand streaming if it causes network spikes.\r\nFinish shader compilation. Compare the built-in benchmark where available.";break;
   case "Minecraft Java":detail="Render 16 / simulation 8 chunks for balance; 12 / 6 for competitive FPS.\r\nThese distances often matter more than resolution in CPU-limited worlds.\r\nVanilla/light mods: start around 4 GB heap; larger packs need pack-specific guidance.\r\nKeep your mods/resource packs intact. This patch only edits distances, V-Sync and cap.";break;
   case "Escape from Tarkov":detail="Textures appropriate to available VRAM; shadows Low, object LOD around 2 to start.\r\nTry overall visibility 1500; lower HBAO/SSR and grass shadows where exposed.\r\nCompare native/TAA against DLSS Quality for distant target clarity.\r\nUse the same offline route/map/weather; online AI and server conditions vary.";break;}
   guide.Text=common+detail+"\r\n\r\nLATENCY: V-Sync Off permits tearing. For a VRR setup, benchmark a cap below refresh\r\n(e.g. 197 at 200 Hz); this is a starting point, not a universal optimal cap.";
  }
  Dictionary<string,string> Changes(){bool c=quality.SelectedIndex==1;if(game.Text=="Minecraft Java")return new Dictionary<string,string>{{"renderDistance",render.Value.ToString()},{"simulationDistance",simulation.Value.ToString()},{"maxFps",cap.Value.ToString()},{"enableVsync",vsync.Checked?"true":"false"}};return new Dictionary<string,string>{{"bMotionBlur","False"},{"bUseVSync",vsync.Checked?"True":"False"},{"FrameRateLimit",cap.Value.ToString(System.Globalization.CultureInfo.InvariantCulture)+".000000"}};}
  void EnsureClosed(){var names=Process.GetProcesses();try{if(names.Any(x=>{try{string n=x.ProcessName;return game.Text=="Fortnite"?n.StartsWith("Fortnite",StringComparison.OrdinalIgnoreCase):n.Equals("javaw",StringComparison.OrdinalIgnoreCase)||n.Equals("java",StringComparison.OrdinalIgnoreCase)||n.Equals("Minecraft",StringComparison.OrdinalIgnoreCase);}catch{return false;}}))throw new Exception("Close the game before editing or restoring its config. Java processes must be closed for Minecraft edits.");}finally{foreach(var p in names)p.Dispose();}}
  byte[] MakePatch(byte[] b){if(game.Text=="Minecraft Java")return Config.Patch(b,Changes(),null,':');var edits=Changes();if(noFrameGen.Checked)edits["bEnableDLSSFrameGeneration"]="False";if(noNanite.Checked)edits["bUseNanite"]="False";if(resolution.SelectedIndex>0){var xy=resolution.Text.Split(new[]{" x "},StringSplitOptions.None);edits["ResolutionSizeX"]=xy[0];edits["ResolutionSizeY"]=xy[1];edits["LastUserConfirmedResolutionSizeX"]=xy[0];edits["LastUserConfirmedResolutionSizeY"]=xy[1];}b=Config.Patch(b,edits,Config.FortniteSection,'=');return Config.Patch(b,graphicOptions.ToDictionary(k=>k.Key,k=>k.Value.SelectedIndex.ToString()),"ScalabilityGroups",'=');}
  void PreviewConfig(){if(game.Text!="Fortnite"&&game.Text!="Minecraft Java")throw new Exception("Use the checklist in this game's settings menu.");EnsureClosed();if(configPath==null||!File.Exists(configPath))throw new Exception("Config not found. Launch the game once or select your instance's config.");string expected=game.Text=="Fortnite"?"GameUserSettings.ini":"options.txt";if(!Path.GetFileName(configPath).Equals(expected,StringComparison.OrdinalIgnoreCase))throw new Exception("Expected "+expected);ClearPreview();previewOriginal=File.ReadAllBytes(configPath);proposed=MakePatch(previewOriginal);previewPath=configPath;var lines=new List<string>();var old=Decode(previewOriginal).Split('\n');var next=Decode(proposed).Split('\n');for(int i=0;i<old.Length;i++)if(old[i]!=next[i])lines.Add(old[i].TrimEnd()+"  ->  "+next[i].TrimEnd());preview.Text=lines.Count==0?"Already matches these settings.":string.Join("\r\n",lines);Status("Preview ready. Apply creates a byte-exact backup first.");}
  static string Decode(byte[] bytes){using(var s=new StreamReader(new MemoryStream(bytes),Encoding.UTF8,true))return s.ReadToEnd();}
  void ApplyConfig(){if(lockConfigEdits.Checked)throw new Exception("External config edits are locked. Use the in-game checklist, or turn off the lock in Session mode before editing.");if(proposed==null||previewOriginal==null||previewPath!=configPath)throw new Exception("Preview the current settings first.");EnsureClosed();if(!File.ReadAllBytes(configPath).SequenceEqual(previewOriginal))throw new Exception("The config changed since preview. Preview it again.");journal.FileEdit(configPath,proposed);ClearPreview();Status("Game config applied and backed up. Launch the game and verify its settings.");}
  void BuildApps(){var p=Page("Background apps","Give the game room.","Select optional apps you actually want to quiet. Discord is opt-in so voice chat stays available.\r\nGraceful close sends a normal window-close request; it never force-kills unsaved work.");apps=new CheckedListBox{Width=860,Height=285,BackColor=panel,ForeColor=ink,BorderStyle=BorderStyle.FixedSingle,CheckOnClick=true};p.Controls.Add(apps);var r=Row();r.Controls.Add(Button("Refresh app list",RefreshApps));r.Controls.Add(Button("Lower selected priority",LowerSelected));r.Controls.Add(Button("Close selected gracefully",CloseSelected));p.Controls.Add(r);var r2=Row();r2.Controls.Add(Button("Restore app priorities",RestorePriorities));r2.Controls.Add(Button("Open startup apps",delegate{Open("ms-settings:startupapps");}));p.Controls.Add(r2);p.Controls.Add(Note("Only browsers, Discord, Spotify, Teams, Slack and Zoom are eligible. Process identity is rechecked\r\nbefore each action. Launchers, games, anti-cheat, audio, input devices and Windows services\r\nare excluded. Lowered priorities restore on app exit or through Recovery after a crash.\r\n\r\nClosing a window may leave tray processes alive; use that app's own Exit command if needed.\r\nClosed apps are not automatically relaunched. Reducing priority does not free RAM.",140));}
  void RefreshApps(){apps.Items.Clear();foreach(var p in Process.GetProcesses())using(p)try{if(allowed.Contains(p.ProcessName,StringComparer.OrdinalIgnoreCase)&&p.SessionId==Process.GetCurrentProcess().SessionId){apps.Items.Add(new AppRow{Pid=p.Id,Started=p.StartTime.ToUniversalTime().Ticks,Name=p.ProcessName+"  |  PID "+p.Id+"  |  "+(p.WorkingSet64/1048576)+" MB  |  "+p.PriorityClass});}}catch{}Status(apps.Items.Count+" eligible processes; nothing selected automatically.");}
  Process Verified(AppRow a){var p=Process.GetProcessById(a.Pid);if(p.StartTime.ToUniversalTime().Ticks!=a.Started||!allowed.Contains(p.ProcessName,StringComparer.OrdinalIgnoreCase)||p.SessionId!=Process.GetCurrentProcess().SessionId){p.Dispose();throw new Exception("Process identity changed. Refresh the list.");}return p;}
  void LowerSelected(){int done=0;var errors=new List<string>();foreach(AppRow a in apps.CheckedItems)try{using(var p=Verified(a))journal.LowerPriority(p);done++;}catch(Exception e){errors.Add(e.Message);}Status(done+" priority requests completed. "+string.Join("; ",errors));RefreshApps();if(errors.Count>0)Status(string.Join("; ",errors));}
  void CloseSelected(){int done=0,skipped=0;foreach(AppRow a in apps.CheckedItems)try{using(var p=Verified(a)){if(p.CloseMainWindow())done++;else skipped++;}}catch{skipped++;}Status(done+" close requests sent; "+skipped+" processes had no window or were unavailable. Save prompts remain visible.");}
  void RestorePriorities(){var errors=new List<string>();foreach(var c in journal.Items.Where(x=>x.Kind=="Priority"&&x.Status!="Restored").Reverse().ToArray())try{journal.Restore(c);}catch(Exception e){errors.Add(e.Message);}Status(errors.Count==0?"App priorities restored (exited processes need no action).":string.Join("; ",errors));}
  void BuildBench(){var p=Page("Compare runs","Prove the improvement.","Import two frame-time CSV captures of the same scene, resolution and duration.\r\nThis analyzes recorded frames; it does not measure input-to-photon latency or claim an FPS boost.");var r=Row();r.Controls.Add(Button("Load baseline CSV",delegate{LoadFrames(false);}));r.Controls.Add(Button("Load tuned CSV",delegate{LoadFrames(true);}));r.Controls.Add(Button("Export comparison",delegate{if(baseline==null||tuned==null)throw new Exception("Load both captures first.");SaveText(benchText.Text,"comparison.txt");}));p.Controls.Add(r);benchA=Note("BASELINE   No capture loaded",57);benchB=Note("TUNED       No capture loaded",57);p.Controls.Add(benchA);p.Controls.Add(benchB);chart=new FrameChart{Width=860,Height=170,BackColor=panel};p.Controls.Add(chart);benchText=Box(112);p.Controls.Add(benchText);p.Controls.Add(Note("Protocol: warm shaders, use the same route for 60-120 seconds, and repeat baseline/tuned\r\nthree times. Keep the change only if gains exceed run-to-run variation. Include stutters.\r\nAccepted ms columns: FrameTimeMs, FrameTime, MsBetweenPresents, CPUFrameTime.\r\nExport one game process / swapchain only. No overlay, capture driver or injector is installed.",100));}
  void LoadFrames(bool b){using(var d=new OpenFileDialog{Filter="Frame-time CSV|*.csv"})if(d.ShowDialog()==DialogResult.OK){var stats=FrameStats.Load(d.FileName);var other=b?baseline:tuned;if(other!=null&&!stats.Metric.Equals(other.Metric,StringComparison.OrdinalIgnoreCase))throw new Exception("Capture metrics differ ("+stats.Metric+" vs "+other.Metric+"). Export the same frame-time metric for both runs.");if(b){tuned=stats;benchB.Text="TUNED  "+stats.Summary();}else{baseline=stats;benchA.Text="BASELINE  "+stats.Summary();}chart.A=baseline;chart.B=tuned;chart.Invalidate();if(baseline!=null&&tuned!=null){benchText.Text=string.Format("Average FPS: {0:+0.0;-0.0;0}%   |   1% low: {1:+0.0;-0.0;0}%   |   p99 time: {2:+0.0;-0.0;0}%\r\nLower p99 is better. FPS gains should also improve lows, not just the average.\r\n1% / 0.1% low = 1000 / mean of the slowest 1% / 0.1% of frames.\r\nBaseline: {3}\r\nTuned: {4}",100*(tuned.AverageFps/baseline.AverageFps-1),100*(tuned.Low1/baseline.Low1-1),100*(tuned.P99/baseline.P99-1),baseline.Summary(),tuned.Summary());if(Math.Abs(tuned.Duration/baseline.Duration-1)>.2)benchText.Text+="\r\nCAUTION: capture durations differ by more than 20%.";}Status("CSV imported. Frame time is not end-to-end latency.");}}
  void BuildRecovery(){var p=Page("Recovery","Every change has a way back.","Restore newest changes first. If another app changed a setting later, FramePilot keeps that\r\nnewer value and reports a conflict. Backups remain available in your local data folder.");history=new ListBox{Width=860,Height=245,BackColor=panel,ForeColor=ink};p.Controls.Add(history);var r=Row();r.Controls.Add(Button("Refresh history",RefreshHistory));r.Controls.Add(Button("Restore selected",delegate{var c=history.SelectedItem as HistoryRow;if(c==null)throw new Exception("Select a change first.");GuardRestore(c.Change);Status(journal.Restore(c.Change));RefreshHistory();}));r.Controls.Add(Button("Restore all outstanding",RestoreAll));p.Controls.Add(r);var r2=Row();r2.Controls.Add(Button("Open backups folder",delegate{Open(data);}));r2.Controls.Add(Button("Export change log",delegate{SaveText(string.Join("\r\n",journal.Items.Select(c=>c.Created+" | "+c.Kind+" | "+c.Target+" | "+c.Name+" | "+c.Status)),"changes.txt");}));p.Controls.Add(r2);recovery=Box(120);p.Controls.Add(recovery);history.SelectedIndexChanged+=delegate{var h=history.SelectedItem as HistoryRow;recovery.Text=h==null?"":h.Change.Kind+"\r\nTarget: "+h.Change.Target+"\r\nBefore: "+h.Change.Before+"\r\nAfter: "+h.Change.After+"\r\nStatus: "+h.Change.Status;};}
  sealed class HistoryRow{public Change Change;public override string ToString(){return Change.Created+"   "+Change.Kind+"   "+Change.Name+"   ["+Change.Status+"]";}}
  void RefreshHistory(){history.Items.Clear();foreach(var c in journal.Items.AsEnumerable().Reverse())history.Items.Add(new HistoryRow{Change=c});}
  void GuardRestore(Change c){if(c.Kind!="File")return;if(lockConfigEdits.Checked)throw new Exception("External config edits are locked. Disable the lock in Session mode before restoring a config.");foreach(var p in Process.GetProcesses())using(p)try{string n=p.ProcessName;if(n.StartsWith("Fortnite",StringComparison.OrdinalIgnoreCase)||n.Equals("java",StringComparison.OrdinalIgnoreCase)||n.Equals("javaw",StringComparison.OrdinalIgnoreCase)||n.Equals("Minecraft",StringComparison.OrdinalIgnoreCase))throw new InvalidOperationException("Close Fortnite and Minecraft / Java before restoring game configs.");}catch(InvalidOperationException){throw;}catch{}}
  void RestoreAll(){var errors=new List<string>();foreach(var c in journal.Items.AsEnumerable().Reverse().Where(x=>x.Status!="Restored").ToArray())try{GuardRestore(c);journal.Restore(c);}catch(Exception e){errors.Add(c.Name+": "+e.Message);}RefreshHistory();recovery.Text=errors.Count==0?"All outstanding changes restored.":string.Join("\r\n",errors);Status(errors.Count==0?"Restore complete.":errors.Count+" changes need attention. See details below.");}
  void BuildAbout(){var p=Page("About & sources","Useful controls. Honest limits.","FramePilot 3.1 / portable Windows desktop app / source available in the full package\r\nNo account, background service or automatic startup. Online driver checks run on request.");p.Controls.Add(Note("This app uses normal user-mode Windows APIs and plain-text settings. It does not read game\r\nmemory, inject code, install drivers, automate gameplay or change anti-cheat/security services.\r\nNo third-party app can promise zero ban risk; publishers control enforcement.\r\n\r\nIt avoids timer/HPET tweaks, core parking hacks, standby-list cleaners, service stripping,\r\nnetwork registry recipes, real-time game priority and automatic overclocking.\r\n\r\nGame presets are reasoned starting points. Real improvements require A/B measurement.\r\nThe linked YouTube page was accessible, but its video/transcript could not be reviewed here.",205));
   var links=new[]{new[]{"NVIDIA: system latency guide","https://www.nvidia.com/en-gb/geforce/guides/system-latency-optimization-guide/"},new[]{"Microsoft: windowed game optimizations","https://support.microsoft.com/en-au/windows/hardware/display-graphics/optimizations-for-windowed-games-in-windows-11"},new[]{"Epic: Fortnite competitive settings","https://store.epicgames.com/news/fortnite-on-pc-best-settings-for-competitive-play-in-2026"},new[]{"Minecraft: memory allocation","https://help.minecraft.net/hc/en-us/articles/39083573916941"},new[]{"NVIDIA: FrameView capture tool","https://www.nvidia.com/en-us/geforce/technologies/frameview/"}};foreach(var l in links){string url=l[1];p.Controls.Add(Button(l[0],delegate{Open(url);}));}
  }
  static void Open(string target){Process.Start(new ProcessStartInfo(target){UseShellExecute=true});}
  void SaveText(string text,string name){using(var d=new SaveFileDialog{FileName=name,Filter="Text report|*.txt"})if(d.ShowDialog()==DialogResult.OK){File.WriteAllText(d.FileName,text,Encoding.UTF8);Status("Report saved.");}}
 }
 public sealed class FrameChart:Control {
  public FrameStats A,B;public FrameChart(){DoubleBuffered=true;}
  protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);var g=e.Graphics;g.SmoothingMode=System.Drawing.Drawing2D.SmoothingMode.AntiAlias;g.DrawString("FRAME TIME / ms     baseline: blue     tuned: mint     lower is better",Font,Brushes.LightGray,12,8);if(A==null&&B==null)return;double max=Math.Max(A==null?0:A.Frames.Max(),B==null?0:B.Frames.Max());g.DrawString(max.ToString("0.0")+" ms peak | Each horizontal bucket shows its worst frame",Font,Brushes.LightGray,12,Height-24);Draw(g,A,Color.CornflowerBlue,max);Draw(g,B,Color.FromArgb(232,150,74),max);}
  void Draw(Graphics g,FrameStats s,Color c,double max){if(s==null)return;int buckets=Math.Min(Width-30,s.Count);var pts=new PointF[buckets];for(int i=0;i<buckets;i++){int start=i*s.Count/buckets,end=(i+1)*s.Count/buckets;double peak=0;for(int j=start;j<end;j++)peak=Math.Max(peak,s.Frames[j]);pts[i]=new PointF(15+i*(Width-30f)/(buckets-1),Height-35-(float)(peak/max)*(Height-70));}using(var pen=new Pen(c,1.5f))g.DrawLines(pen,pts);}
 }
